package com.mamtrex.hospital.patient; import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.auth.ActingContext; import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.organization.BranchRepository; import com.mamtrex.hospital.shared.NotFoundException; import org.springframework.dao.DuplicateKeyException; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*; @Service @Transactional public class PatientService { private final PatientRepository repo; private final BranchRepository branches; private final AuditService audit; public PatientService(PatientRepository r,BranchRepository b,AuditService a){repo=r;branches=b;audit=a;} /* Task 4 (docs/plan3.md): branch ownership derives from the acting context, never client input; list/detail/search/update resolve only inside the acting branch and a cross-branch id 404s like a nonexistent one. Global MRN uniqueness is unchanged. */ public Patient create(String mrn,String name,LocalDate dob,String sex,String phone,String email,String nationalId,String address){repo.findByMedicalRecordNumber(mrn).ifPresent(existing->{throw new DuplicateKeyException("Medical record number already exists");});var p=repo.save(new Patient(actingBranch(),mrn,name,dob,sex,phone,email,nationalId,address));audit.record("CREATE","Patient",p.getId().toString(),mrn);return p;} @Transactional(readOnly=true) public Patient get(UUID id){return repo.findByIdAndBranchId(id,actingBranchId()).orElseThrow(()->new NotFoundException("Patient not found: "+id));} @Transactional(readOnly=true) public List<Patient> list(String q){UUID branchId=actingBranchId();return q==null||q.isBlank()?repo.findByBranchId(branchId):repo.findByBranchIdAndFullNameContainingIgnoreCase(branchId,q);} public Patient update(UUID id,String name,String phone,String email,String address){var p=get(id);p.update(name,phone,email,address);audit.record("UPDATE","Patient",id.toString(),"profile");return p;} private UUID actingBranchId(){return actingBranch().getId();} private Branch actingBranch(){return branches.findById(currentContext().branchId()).orElseThrow(()->new AccessDeniedException("The acting branch is not available"));} /* Fail-closed seam: the JWT filter guarantees an ActingContext principal and an existing active selected branch for every authorized request; anything else is refused, never guessed. */ private static ActingContext currentContext(){var a=SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.getPrincipal() instanceof ActingContext c)return c;throw new AccessDeniedException("No acting context is available");} }
